Concurrency Patterns > Worker Pools > Example

```python
import queue
import threading

jobs = queue.Queue()
results = []

def worker():
    while True:
        item = jobs.get()
        if item is None:
            break
        results.append(item * 2)
        jobs.task_done()

threads = [threading.Thread(target=worker) for _ in range(4)]
for t in threads:
    t.start()
for n in range(20):
    jobs.put(n)
for _ in threads:
    jobs.put(None)
for t in threads:
    t.join()
```

